-- Run after pdf_publication.sql in the same rollback-only fixture transaction.
reset role;
update public.admin_access set enabled=true where user_id=pg_temp.pp_id(98);
create function pg_temp.preparation(n integer default 80) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.pp_id(1000+n),'expectedVersion',0,'publication',pg_temp.pp_mixed(n)||jsonb_build_object('gameVersion',4,'basePublicationVersion',3))$$;
grant execute on function pg_temp.preparation(integer) to anon,authenticated,service_role;
set local role authenticated;
set local request.jwt.claim.sub='f9300000-0000-4000-8000-000000000098';
select pg_temp.pp_assert(public.get_pdf_publication_preparation(pg_temp.pp_id(100)) is null,'no unsaved preparation');
select pg_temp.pp_assert(public.save_pdf_publication_preparation(pg_temp.preparation())->'version'='1','save preparation without publishing');
select pg_temp.pp_assert(public.get_public_game(pg_temp.pp_id(8))->'version'='3','save does not change public version');
select pg_temp.pp_assert(public.get_pdf_publication_preparation(pg_temp.pp_id(100))->'publication'=pg_temp.preparation()->'publication','all decisions and tokens survive a fresh read');
select pg_temp.pp_assert(public.save_pdf_publication_preparation(pg_temp.preparation())->'version'='1','response loss is idempotent');
select pg_temp.pp_error('select public.save_pdf_publication_preparation(pg_temp.preparation(81))','PT409');
select pg_temp.pp_error($q$select public.save_pdf_publication_preparation(jsonb_set(pg_temp.preparation(),'{publication,reason}','"Other reason with same command"'))$q$,'PT409');
select pg_temp.pp_error($q$select public.save_pdf_publication_preparation(jsonb_set(pg_temp.preparation(82),'{publication,source,reviewVersion}','1')||'{"expectedVersion":1}'::jsonb)$q$,'PT409');
select pg_temp.pp_error($q$select public.save_pdf_publication_preparation(jsonb_set(pg_temp.preparation(83),'{publication,supplement,rows,0,starter}','false')||'{"expectedVersion":1}'::jsonb)$q$,'PT400');
select pg_temp.pp_error($q$select public.save_pdf_publication_preparation(jsonb_set(pg_temp.preparation(84),'{publication,authority,periodScores}','"pdf"')||'{"expectedVersion":1}'::jsonb)$q$,'PT400');
select pg_temp.pp_assert(public.publish_pdf_game(public.get_pdf_publication_preparation(pg_temp.pp_id(100))->'publication')->'version'='4','saved frozen command can publish independently');
select pg_temp.pp_assert(public.publish_pdf_game(public.get_pdf_publication_preparation(pg_temp.pp_id(100))->'publication')->'version'='4','saved publication command replays after commit');
select pg_temp.pp_assert(public.save_pdf_publication_preparation(pg_temp.preparation())->'version'='1','save receipt still replays without publishing again');
select pg_temp.pp_error('select public.save_pdf_publication_preparation(pg_temp.preparation(85)||''{"expectedVersion":1}''::jsonb)','PT409');
set local request.jwt.claim.sub='f9300000-0000-4000-8000-000000000099';
select pg_temp.pp_error('select public.get_pdf_publication_preparation(pg_temp.pp_id(100))','PT403');
select pg_temp.pp_error('select public.save_pdf_publication_preparation(pg_temp.preparation())','PT403');
set local role anon;
select pg_temp.pp_error('select public.get_pdf_publication_preparation(pg_temp.pp_id(100))','42501');
select pg_temp.pp_error('select * from private.pdf_publication_preparations','42501');
reset role;
update public.admin_access set enabled=false where user_id=pg_temp.pp_id(98);
set local role authenticated;
set local request.jwt.claim.sub='f9300000-0000-4000-8000-000000000098';
select pg_temp.pp_error('select public.save_pdf_publication_preparation(pg_temp.preparation())','PT403');
reset role;
